test('re-ranking a review record keeps its member identities (never stale), compares its own numbers, ranks in subset mode with its searches\' and iTunes stage\'s exact flags and applies a sole preselection only while the run applied nothing', () => {
    // Two members whose durations fit the synthetic releases' first two tracks: the two-track release and a three-track one both match.
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Lead'], members: numberedMembers([210_000, 220_000]) });
    const longer = synthetic(3, { trackCount: 3, media: [{ position: 1, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song'), track(3, 'Bonus Song')] }] });
    const files = catalogReviewLookupFileSet(doc).files, before = copy(doc);
    const run = completed(doc, [stored(synthetic(1)), stored(longer)], { input: { trigger: 'catalog', submitted: null }, grantSource: 'create', files, exactSearchComplete: true });
    assert.equal(rerankStoredLookup(doc, run, now), null, 'unchanged evidence re-ranks nothing');
    // A ranking against other evidence is re-ranked with the run's exact flag: the exact-count group is preselected and, while the
    // run has applied nothing, applied to the review's draft as the confirming administrator.
    const outdated = { ...run, ranking: { ...run.ranking!, files: [] } };
    const applying = copy(doc), reranked = rerankStoredLookup(applying, outdated, now, other)!;
    assert.deepEqual([reranked.changed, reranked.record.ranking!.preselection?.basis, reranked.record.ranking!.preselection?.candidateKey, reranked.record.ranking!.completeness,
        reranked.record.applied?.choice, reranked.record.applied?.candidateKey, reranked.record.applied?.actorId, reranked.record.applied?.pairs, reranked.record.files, reranked.record.staleSlotIds],
    [true, 'exactTrackCount', `musicbrainz:${mbid(1)}`, { exact: true, subset: true }, 'preselected', `musicbrainz:${mbid(1)}`, other,
        [{ slotId: files[0].slotId, discNumber: 1, trackNumber: 1 }, { slotId: files[1].slotId, discNumber: 1, trackNumber: 2 }], files, []]);
    assert.equal((applying.draft as ImportDraftV2 & { album: { expectedTracklist: unknown[] } }).album.expectedTracklist.length, 2);
    assert.ok(reranked.record.ranking!.candidates.every(candidate => candidate.comparison?.subset !== undefined));
    // An application of this run (its preselection, a choice or none) stays as it is: the re-rank stores the ranking only.
    for (const applied of [{ ...reranked.record.applied!, candidateKey: `musicbrainz:${mbid(3)}`, releaseId: mbid(3) }, { ...reranked.record.applied!, choice: 'chosen' as const },
        { ...reranked.record.applied!, choice: 'none' as const, candidateKey: null, releaseId: null }]) {
        const kept = copy(doc), result = rerankStoredLookup(kept, { ...outdated, applied }, now, other)!;
        assert.deepEqual([result.changed, result.record.applied, result.record.ranking!.preselection?.basis, kept], [false, applied, 'exactTrackCount', doc], applied.choice);
    }
    assert.deepEqual(doc, before, 'nothing is written to the review the re-ranks above copied');
    // Without the exact flag (incomplete, or absent), two matching groups preselect nothing.
    for (const flag of [false, undefined]) {
        const partial = rerankStoredLookup(doc, { ...outdated, exactSearchComplete: flag }, now)!;
        assert.deepEqual([partial.record.ranking!.preselection, partial.record.ranking!.completeness], [null, { exact: false, subset: true }], String(flag));
    }
    // The run's iTunes stage counts too: one that left out only collections with more tracks than members keeps the exact-count
    // preselection; one that left out a collection that could match exactly, or a stage without its own flag, does not.
    const stage = (flags: { exactComplete?: boolean }): LookupItunesStage => ({ reason: 'noMatch', text: null, requests: [], requestIndex: 0, items: [], bridge: [], bridgeIndex: 0,
        bridgeOutcomes: [], state: 'answered', complete: false, finalized: true, ...flags });
    for (const [flags, basis, completeness] of [[{ exactComplete: true }, 'exactTrackCount', { exact: true, subset: false }], [{ exactComplete: false }, undefined, { exact: false, subset: false }],
        [{}, undefined, { exact: false, subset: false }]] as const) {
        const ranked = rerankStoredLookup(copy(doc), { ...outdated, itunesStage: stage(flags) }, now)!.record.ranking!;
        assert.deepEqual([ranked.preselection?.basis, ranked.completeness], [basis, completeness], JSON.stringify(flags));
    }
    // A member's own Track Number is ranking evidence for a review (an import ignores numbers, which its applications write).
    assert.equal(lookupRerankNeeded(doc, reranked.record), false);
    (doc.draft as ImportDraftV2).tracks[0].trackNumber = 3;
    assert.equal(lookupRerankNeeded(doc, reranked.record), true);
    const renumbered = rerankStoredLookup(doc, reranked.record, now)!;
    assert.deepEqual([renumbered.record.ranking!.files[0].trackNumber, renumbered.record.ranking!.preselection, renumbered.changed, renumbered.record.applied], [3, null, false, reranked.record.applied]);
    // A number lookup wrote (automatic) never constrains pairing.
    doc.draftOrigins = { [`tracks:${(doc.draft as ImportDraftV2).tracks[0].slotId}:trackNumber`]: 'automatic' };
    assert.equal(rerankStoredLookup(doc, renumbered.record, now)!.record.ranking!.files[0].trackNumber, null);
});

// Existing-Album reviews (format 3): a candidate's values reach only the review's private draft, compared under the review rules.
type ReviewDraft = Omit<ImportDraftV2, 'album' | 'tracks'> & { album: ImportDraftV2['album'] & { expectedTracklist: unknown }; tracks: (ImportDraftV2['tracks'][number] & { artists: ImportArtistEntry[] })[] };
const reviewDraftOf = (doc: AdminImportDocument) => doc.draft as ReviewDraft;
/**
 * A fetched synthetic release `id` with one CD whose tracks last `lengths`, each crediting `credits[index]` (`release`: the release's
 * own credit, stored as its marker; absent: no stored track credit).
 */
const reviewRelease = (id: number, lengths: (number | null)[], options: { title?: string; releaseCredit?: LookupArtistCredit[]; label?: { name: string; labelId: string };
    credits?: (LookupArtistCredit[] | 'release' | undefined)[] | 'release'; date?: { year: number; month: number | null; day: number | null } | null } = {}): StoredLookupCandidate => {
    const credits = options.credits;
    const release = syntheticRelease(syntheticMbid(id), [{ tracks: lengths.map((lengthMs, index) => {
        const own = credits === 'release' ? 'release' : credits?.[index];
        return { lengthMs, ...(own === undefined ? {} : { credit: own }) };
    }) }], { title: options.title, releaseCredit: options.releaseCredit, label: options.label });
    return storedCandidate(options.date === undefined ? release : { ...release, date: options.date });
};
/** The key a review derives for a lookup entry of the Album (no slot) or of a member. */
const reviewKey = (name: string, slotId?: string) => derivedEntryKey({ importId: reviewId, ...(slotId ? { slotId } : {}), lookupEntry: name.toLowerCase() });
const lookupEntry = (key: string, name: string, musicBrainzId: string | null, role: ImportArtistEntry['role'] = 'primary', joinPhrase: string | null = null): ImportArtistEntry =>
    ({ key, name, role, joinPhrase, musicBrainzId });
const aliasContext = (aliases: [string, string[]][]) => ({ identity: { holders: new Map(), storedIds: new Map() }, aliases: new Map(aliases), localized: [] as string[][] });
const none = () => intent({ choice: 'none', basis: null });
const pathsOf = (items: readonly { path: string }[]) => items.map(item => item.path);

test('only a review admits the expected tracklist and member Artist entries as lookup value paths', () => {
    for (const path of ['album.expectedTracklist', `tracks.${reviewSlot(0)}.artists`]) assert.deepEqual([isLookupValuePath(path), isLookupValuePath(path, { review: true })], [false, true], path);
    for (const path of ['album.title', `tracks.${reviewSlot(0)}.trackNumber`]) assert.deepEqual([isLookupValuePath(path), isLookupValuePath(path, { review: true })], [true, true], path);
    for (const path of ['album.visibility', 'tracks.a.b.artists', `tracks.${'x'.repeat(80)}.artists`, 7]) assert.equal(isLookupValuePath(path, { review: true }), false, String(path));
});

test('a review choice fills an empty label, date, expected tracklist and missing Disc Numbers, records conflicts for differing titles, stores its pairing, stages no cover and reads no file tags', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], label: 'none',
        members: [{ durationMs: 200_000, trackNumber: 1, title: 'Own Title' }, { durationMs: 210_000, trackNumber: 2 }] });
    const candidate = reviewRelease(1, [200_000, 210_000, 230_000], { title: 'Looked Up Album', label: { name: 'Looked Up Label', labelId: syntheticMbid(40) }, credits: 'release' });
    candidate.release!.frontArtwork = true;
    const [first, second] = [reviewSlot(0), reviewSlot(1)], rows = [200_000, 210_000, 230_000].map((durationMs, index) =>
        ({ discNumber: 1, trackNumber: index + 1, title: `Synthetic Track ${index + 1}`, durationMs }));
    const { application, changed } = applyLookupCandidate(doc, null, candidate, intent());
    const draft = reviewDraftOf(doc), ensemble = (slotId: string) => [lookupEntry(reviewKey('Synthetic Ensemble', slotId), 'Synthetic Ensemble', syntheticMbid(1))];
    assert.equal(changed, true);
    // Empty values are filled automatically: the label, date, tracklist, missing Disc Numbers and members without Artist Credits.
    assert.deepEqual([draft.album.label, draft.album.releaseDate, draft.album.expectedTracklist, draft.tracks.map(track => [track.discNumber, track.trackNumber, track.title, track.artists])],
        [{ name: 'Looked Up Label', musicBrainzId: syntheticMbid(40) }, { year: 2020, month: null, day: null }, rows,
            [[1, 1, 'Own Title', ensemble(first)], [1, 2, 'Synthetic Track 2', ensemble(second)]]]);
    assert.deepEqual(Object.entries(doc.draftOrigins!).filter(([, origin]) => origin === 'automatic').map(([key]) => key).sort(),
        ['album:expectedTracklist', 'album:label', 'album:releaseDate', `tracks:${first}:artists`, `tracks:${first}:discNumber`, `tracks:${second}:artists`, `tracks:${second}:discNumber`].sort());
    // The agreeing Album entry only gains its ID; differing titles are conflicts and stay as they were.
    assert.deepEqual([draft.album.artists, draft.album.title], [[lookupEntry(reviewEntryKey(0), 'Synthetic Ensemble', syntheticMbid(1))], 'Synthetic Album']);
    assert.deepEqual(application.conflicts, [{ path: 'album.title', lookup: 'Looked Up Album', slotId: null, answer: null },
        { path: `tracks.${first}.title`, lookup: 'Synthetic Track 1', slotId: first, answer: null }]);
    assert.deepEqual([application.pairs, application.flagged], [[{ slotId: first, discNumber: 1, trackNumber: 1 }, { slotId: second, discNumber: 1, trackNumber: 2 }], []]);
    assert.deepEqual(pathsOf(application.values), ['album.label', 'album.releaseDate', 'album.expectedTracklist', `tracks.${first}.discNumber`, `tracks.${first}.artists`,
        `tracks.${second}.discNumber`, `tracks.${second}.artists`]);
    assert.deepEqual(application.musicBrainzIds, [{ path: 'album.artists', entryKey: reviewEntryKey(0), musicBrainzId: syntheticMbid(1) }, { path: 'album.label', entryKey: null, musicBrainzId: syntheticMbid(40) },
        { path: `tracks.${first}.artists`, entryKey: reviewKey('Synthetic Ensemble', first), musicBrainzId: syntheticMbid(1) },
        { path: `tracks.${second}.artists`, entryKey: reviewKey('Synthetic Ensemble', second), musicBrainzId: syntheticMbid(1) }]);
    // A review stages no artwork, and its conflicts block applying until answered.
    assert.equal(doc.media, undefined);
    assert.deepEqual(lookupAnswersNeeded({ run: 1, applied: application }, doc, { append: false }).conflicts, ['album.title', `tracks.${first}.title`]);
    // Choosing none returns every automatic value to empty (a review has no file tags) and removes the ID it added.
    const cleared = applyLookupCandidate(doc, application, null, none());
    assert.deepEqual([draft.album.label, draft.album.releaseDate, draft.album.expectedTracklist, draft.tracks.map(track => [track.discNumber, track.artists]), draft.album.artists[0].musicBrainzId,
        cleared.application.pairs, Object.values(doc.draftOrigins!).includes('automatic')], [null, null, null, [[null, []], [null, []]], null, null, false]);
});

test('review Artist entries agree by an alias, by a stored ID under another credited name and by byline phrases; reordered entries are one conflict keeping the saved keys', () => {
    const one = [200_000];
    // A saved name the run found as an alias of the credited artist agrees, and gains its ID; without the alias it is a conflict.
    const alias = reviewLookupDocument({ albumEntries: [{ name: 'シンセ アンサンブル' }] });
    const aliased = applyLookupCandidate(alias, null, reviewRelease(1, one), intent(), aliasContext([[syntheticMbid(1), ['シンセ アンサンブル']]]));
    assert.deepEqual([reviewDraftOf(alias).album.artists, aliased.application.conflicts], [[lookupEntry(reviewEntryKey(0), 'シンセ アンサンブル', syntheticMbid(1))], []]);
    const unknown = reviewLookupDocument({ albumEntries: [{ name: 'シンセ アンサンブル' }] });
    assert.deepEqual(pathsOf(applyLookupCandidate(unknown, null, reviewRelease(1, one), intent()).application.conflicts), ['album.artists']);
    // An entry whose Artist keeps the credited ID agrees under another credited name, and keeps its saved name.
    const renamed = reviewLookupDocument({ albumEntries: [{ name: 'Old Name', musicBrainzId: syntheticMbid(1) }] });
    const kept = applyLookupCandidate(renamed, null, reviewRelease(1, one, { releaseCredit: credit('New Name', syntheticMbid(1)) }), intent());
    assert.deepEqual([reviewDraftOf(renamed).album.artists, kept.application.conflicts, kept.application.musicBrainzIds], [[lookupEntry(reviewEntryKey(0), 'Old Name', syntheticMbid(1))], [], undefined]);
    // "A, B" saved without join phrases agrees with a `, ` credit.
    const pair = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Lead' }, { name: 'Synthetic Second' }] });
    const comma: LookupArtistCredit[] = [{ name: 'Synthetic Lead', joinPhrase: ', ', artistId: syntheticMbid(1), artistName: 'Synthetic Lead' },
        { name: 'Synthetic Second', joinPhrase: '', artistId: syntheticMbid(2), artistName: 'Synthetic Second' }];
    const joined = applyLookupCandidate(pair, null, reviewRelease(1, one, { releaseCredit: comma }), intent());
    assert.deepEqual([joined.application.conflicts, reviewDraftOf(pair).album.artists.map(item => [item.joinPhrase, item.musicBrainzId])], [[], [[null, syntheticMbid(1)], [null, syntheticMbid(2)]]]);
    // The same entries in another order are one conflict, whose lookup entries keep the keys of the saved entries they agree with.
    const reordered = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Lead' }, { name: 'Synthetic Second' }] });
    const swapped = applyLookupCandidate(reordered, null, reviewRelease(1, one, { releaseCredit: [{ ...comma[1], joinPhrase: ', ' }, { ...comma[0], joinPhrase: '' }] }), intent());
    assert.deepEqual(swapped.application.conflicts, [{ path: 'album.artists', slotId: null, answer: null, lookup: [lookupEntry(reviewEntryKey(1), 'Synthetic Second', syntheticMbid(2), 'primary', ', '),
        lookupEntry(reviewEntryKey(0), 'Synthetic Lead', syntheticMbid(1))] }]);
    assert.deepEqual(reviewDraftOf(reordered).album.artists.map(item => item.name), ['Synthetic Lead', 'Synthetic Second']);
});

test('review entries appended after agreeing saved entries are written as the saved list extended; choosing none or another candidate restores the saved list', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }] }), saved = structuredClone(reviewDraftOf(doc).album.artists);
    const featuring = reviewRelease(1, [200_000], { releaseCredit: credit('Synthetic Ensemble', syntheticMbid(1), ['Synthetic Guest', syntheticMbid(2)]) });
    const extended = [lookupEntry(reviewEntryKey(0), 'Synthetic Ensemble', syntheticMbid(1), 'primary', ' feat. '), lookupEntry(reviewKey('Synthetic Guest'), 'Synthetic Guest', syntheticMbid(2), 'featured')];
    const first = applyLookupCandidate(doc, null, featuring, intent());
    // The appended entry and its connecting phrase are written into the saved list, which stays the administrator's own.
    assert.deepEqual([reviewDraftOf(doc).album.artists, doc.draftOrigins!['album:artists'], first.application.conflicts, first.application.paths.includes('album.artists')],
        [extended, undefined, [], true]);
    assert.deepEqual(first.application.values.find(item => item.path === 'album.artists'), { path: 'album.artists', value: extended, slotId: null, kept: saved });
    assert.deepEqual(first.application.musicBrainzIds!.filter(item => item.path === 'album.artists').map(item => item.entryKey), [reviewEntryKey(0), reviewKey('Synthetic Guest')]);
    // The same candidate again writes nothing.
    const valueRevision = doc.valueRevision, again = applyLookupCandidate(doc, first.application, featuring, intent());
    assert.deepEqual([again.changed, again.application.paths, reviewDraftOf(doc).album.artists, doc.valueRevision], [false, [], extended, valueRevision]);
    // Choosing none restores the saved list, without the IDs the candidate gave it.
    const cleared = applyLookupCandidate(doc, again.application, null, none());
    assert.deepEqual([reviewDraftOf(doc).album.artists, cleared.application.paths.includes('album.artists'), cleared.application.values], [saved, true, []]);
    // A candidate crediting only the saved artist compares with the restored saved list: it agrees and only adds its ID.
    const extendedAgain = applyLookupCandidate(doc, cleared.application, featuring, intent());
    const plain = applyLookupCandidate(doc, extendedAgain.application, reviewRelease(2, [200_000]), intent());
    assert.deepEqual([reviewDraftOf(doc).album.artists, plain.application.conflicts], [[lookupEntry(reviewEntryKey(0), 'Synthetic Ensemble', syntheticMbid(1))], []]);
    // A list changed since it was extended is no longer restored.
    const changed = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }] }), applied = applyLookupCandidate(changed, null, featuring, intent()).application;
    reviewDraftOf(changed).album.artists[1].joinPhrase = ' & ';
    applyLookupCandidate(changed, applied, null, none());
    assert.equal(reviewDraftOf(changed).album.artists.length, 2);
});

test('a changed join phrase and an added name equal to a saved one are each one conflict on the whole list; another MusicBrainz ID under the same name is an ID conflict', () => {
    // A join phrase between entries that differs as bylines present it.
    const phrase = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Lead', joinPhrase: ' & ' }, { name: 'Synthetic Second' }] });
    const comma: LookupArtistCredit[] = [{ name: 'Synthetic Lead', joinPhrase: ', ', artistId: syntheticMbid(1), artistName: 'Synthetic Lead' },
        { name: 'Synthetic Second', joinPhrase: '', artistId: syntheticMbid(2), artistName: 'Synthetic Second' }];
    assert.deepEqual(pathsOf(applyLookupCandidate(phrase, null, reviewRelease(1, [200_000], { releaseCredit: comma }), intent()).application.conflicts), ['album.artists']);
    // An entry whose Artist keeps another ID agrees by its name: it keeps its key, Artist and ID, and the difference is an ID conflict.
    const other = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble', musicBrainzId: syntheticMbid(9) }] }), release = reviewRelease(1, [200_000]);
    const conflicted = applyLookupCandidate(other, null, release, intent());
    const replacing = [lookupEntry(reviewEntryKey(0), 'Synthetic Ensemble', syntheticMbid(1))];
    assert.deepEqual([conflicted.application.conflicts, conflicted.application.musicBrainzIds],
        [[{ path: 'album.artists', slotId: null, answer: null, lookup: replacing, musicBrainzId: true }], undefined]);
    assert.deepEqual(reviewDraftOf(other).album.artists, [lookupEntry(reviewEntryKey(0), 'Synthetic Ensemble', syntheticMbid(9))]);
    const record = { ...completed(other, [release]), applied: conflicted.application };
    assert.deepEqual(lookupAnswersNeeded(record, other, { append: false }).conflicts, ['album.artists']);
    // Only an explicit answer replaces the kept ID, which is then recorded as supplied.
    const answered = resolveLookupConflicts(other, record, { run: 1, candidateKey: release.key, answers: [{ path: 'album.artists', answer: 'lookup', base: structuredClone(reviewDraftOf(other).album.artists) }] }, now);
    assert.deepEqual([reviewDraftOf(other).album.artists, answered.applied!.musicBrainzIds, lookupAnswersNeeded(answered, other, { append: false }).conflicts],
        [replacing, [{ path: 'album.artists', entryKey: reviewEntryKey(0), musicBrainzId: syntheticMbid(1) }], []]);
    // An extended list keeps the kept ID too, with the same ID conflict on the extended list.
    const extended = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble', musicBrainzId: syntheticMbid(9) }] });
    const featuring = applyLookupCandidate(extended, null, reviewRelease(1, [200_000], { releaseCredit: credit('Synthetic Ensemble', syntheticMbid(1), ['Synthetic Guest', syntheticMbid(2)]) }), intent());
    assert.deepEqual(reviewDraftOf(extended).album.artists.map(item => [item.name, item.musicBrainzId]), [['Synthetic Ensemble', syntheticMbid(9)], ['Synthetic Guest', syntheticMbid(2)]]);
    assert.deepEqual(featuring.application.conflicts.map(item => [item.path, item.musicBrainzId, (item.lookup as ImportArtistEntry[]).map(entry => entry.musicBrainzId)]),
        [['album.artists', true, [syntheticMbid(1), syntheticMbid(2)]]]);
    // An appended entry whose name folds to a saved entry's (the saved entry agreeing by its ID) is a conflict, never a merged list.
    const folded = reviewLookupDocument({ albumEntries: [{ name: 'Old Name', musicBrainzId: syntheticMbid(1) }] });
    const merged = applyLookupCandidate(folded, null, reviewRelease(1, [200_000], { releaseCredit: credit('New Name', syntheticMbid(1), ['old name', syntheticMbid(2)]) }), intent());
    assert.deepEqual([pathsOf(merged.application.conflicts), reviewDraftOf(folded).album.artists.length], [['album.artists'], 1]);
});

test('a lookup answer to an extended list\'s ID conflict keeps the saved list: none or another candidate restores it with its kept ID, and the same candidate again keeps the answer', () => {
    const lead = syntheticMbid(1), offered = syntheticMbid(9), partner = syntheticMbid(6);
    const releaseCredit: LookupArtistCredit[] = [{ name: 'Synthetic Lead', joinPhrase: ' & ', artistId: offered, artistName: 'Synthetic Lead' },
        { name: 'Synthetic Partner', joinPhrase: '', artistId: partner, artistName: 'Synthetic Partner' }];
    const release = reviewRelease(1, [200_000], { releaseCredit });
    const saved = [lookupEntry(reviewEntryKey(0), 'Synthetic Lead', lead)];
    const extendedWith = (id: string) => [lookupEntry(reviewEntryKey(0), 'Synthetic Lead', id, 'primary', ' & '), lookupEntry(reviewKey('Synthetic Partner'), 'Synthetic Partner', partner)];
    // Applied and answered: the extended list keeps the saved Lead's ID and gets an ID conflict; answering lookup writes the release's.
    const answeredWith = (answer: 'mine' | 'lookup') => {
        const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Lead', musicBrainzId: lead }] });
        const applied = applyLookupCandidate(doc, null, release, intent()).application;
        assert.deepEqual([reviewDraftOf(doc).album.artists, applied.conflicts.map(item => [item.path, item.musicBrainzId, item.answer])],
            [extendedWith(lead), [['album.artists', true, null]]]);
        const record = resolveLookupConflicts(doc, { ...completed(doc, [release]), applied }, { run: 1, candidateKey: release.key,
            answers: [{ path: 'album.artists', answer, base: structuredClone(reviewDraftOf(doc).album.artists) }] }, now);
        return { doc, applied: record.applied!, record };
    };
    const answered = answeredWith('lookup');
    assert.deepEqual([reviewDraftOf(answered.doc).album.artists, answered.applied.values.find(item => item.path === 'album.artists'),
        lookupAnswersNeeded(answered.record, answered.doc, { append: false }).conflicts],
        [extendedWith(offered), { path: 'album.artists', value: extendedWith(offered), slotId: null, kept: saved }, []]);
    // Choosing none restores the saved list with the ID its Artist keeps, never the answered or the appended entries.
    const cleared = copy(answered.doc), noneApplied = applyLookupCandidate(cleared, answered.applied, null, none());
    assert.deepEqual([reviewDraftOf(cleared).album.artists, noneApplied.application.paths.includes('album.artists'), noneApplied.application.values], [saved, true, []]);
    // Another candidate compares with the restored saved list: the same name under another ID is a new, unanswered ID conflict.
    const other = copy(answered.doc), otherRelease = reviewRelease(2, [200_000], { releaseCredit: credit('Synthetic Lead', offered) });
    const replaced = applyLookupCandidate(other, answered.applied, otherRelease, intent());
    assert.deepEqual([reviewDraftOf(other).album.artists, replaced.application.conflicts.map(item => [item.path, item.musicBrainzId, item.answer])],
        [saved, [['album.artists', true, null]]]);
    // The same candidate again writes the answer again, so nothing changes and the answer stands; none still restores the saved list.
    const again = copy(answered.doc), valueRevision = again.valueRevision, reapplied = applyLookupCandidate(again, answered.applied, release, intent());
    assert.deepEqual([reapplied.changed, reapplied.application.paths, reviewDraftOf(again).album.artists, again.valueRevision,
        reapplied.application.conflicts.map(item => [item.path, item.musicBrainzId, item.answer]), reapplied.application.values.find(item => item.path === 'album.artists')?.kept],
        [false, [], extendedWith(offered), valueRevision, [['album.artists', true, 'lookup']], saved]);
    applyLookupCandidate(again, reapplied.application, null, none());
    assert.deepEqual(reviewDraftOf(again).album.artists, saved);
    // Keeping the current list leaves the extended list as written, and none restores the saved list.
    const kept = answeredWith('mine');
    assert.deepEqual([reviewDraftOf(kept.doc).album.artists, kept.applied.values.find(item => item.path === 'album.artists')?.kept], [extendedWith(lead), saved]);
    applyLookupCandidate(kept.doc, kept.applied, null, none());
    assert.deepEqual(reviewDraftOf(kept.doc).album.artists, saved);
});

test('a saved list holding two names equal case-insensitively is one conflict whose lookup answer parses and replaces it', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Duo' }, { name: 'SYNTHETIC DUO', role: 'featured' }] });
    const candidate = reviewRelease(1, [200_000], { releaseCredit: credit('Synthetic Duo', syntheticMbid(1)) });
    const record = { ...completed(doc, [candidate]), applied: applyLookupCandidate(doc, null, candidate, intent()).application };
    assert.deepEqual(record.applied.conflicts.map(item => [item.path, item.lookup]), [['album.artists', [lookupEntry(reviewEntryKey(0), 'Synthetic Duo', syntheticMbid(1))]]]);
    const answered = resolveLookupConflicts(doc, record, { run: 1, candidateKey: candidate.key, answers: [{ path: 'album.artists', answer: 'lookup', base: structuredClone(reviewDraftOf(doc).album.artists) }] }, now);
    assert.deepEqual([reviewDraftOf(doc).album.artists, doc.draftOrigins!['album:artists'], answered.applied!.conflicts[0].answer, lookupAnswersNeeded(answered, doc, { append: false }).conflicts],
        [[lookupEntry(reviewEntryKey(0), 'Synthetic Duo', syntheticMbid(1))], 'administrator', 'lookup', []]);
    // Keeping the current list leaves it as it is.
    const keep = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Duo' }, { name: 'SYNTHETIC DUO', role: 'featured' }] }), before = structuredClone(reviewDraftOf(keep).album.artists);
    const kept = { ...completed(keep, [candidate]), applied: applyLookupCandidate(keep, null, candidate, intent()).application };
    resolveLookupConflicts(keep, kept, { run: 1, candidateKey: candidate.key, answers: [{ path: 'album.artists', answer: 'mine', base: before }] }, now);
    assert.deepEqual(reviewDraftOf(keep).album.artists, before);
});

test('a review date that only adds precision is a conflict marked so; an import\'s date conflict never carries the mark', () => {
    const date = (releaseDate: { year: number; month: number | null; day: number | null }, lookup: { year: number; month: number | null; day: number | null }) => {
        const doc = reviewLookupDocument({ releaseDate });
        return applyLookupCandidate(doc, null, reviewRelease(1, [200_000], { date: lookup }), intent()).application.conflicts.filter(item => item.path === 'album.releaseDate');
    };
    assert.deepEqual(date({ year: 2020, month: null, day: null }, { year: 2020, month: 5, day: 1 }),
        [{ path: 'album.releaseDate', lookup: { year: 2020, month: 5, day: 1 }, slotId: null, answer: null, precision: true }]);
    assert.deepEqual(date({ year: 2020, month: 5, day: null }, { year: 2020, month: 5, day: 1 })[0].precision, true);
    assert.deepEqual(date({ year: 2019, month: null, day: null }, { year: 2020, month: 5, day: 1 }), [{ path: 'album.releaseDate', lookup: { year: 2020, month: 5, day: 1 }, slotId: null, answer: null }]);
    assert.deepEqual(date({ year: 2020, month: 5, day: 1 }, { year: 2020, month: 5, day: 1 }), []);
    const imported = project(2, timed);
    draftOf(imported).album.releaseDate = { year: 2020, month: null, day: null };
    const conflict = applyLookupCandidate(imported, null, stored(synthetic(1)), intent()).application.conflicts.find(item => item.path === 'album.releaseDate')!;
    assert.deepEqual([conflict.lookup, 'precision' in conflict], [{ year: 2020, month: 3, day: null }, false]);
});

test('a review\'s expected tracklist fills none, conflicts with another, keeps an equal one, is left out over its bounds and is never flagged for the draft cap', () => {
    const lengths = [200_000, 210_000], rows = lengths.map((durationMs, index) => ({ discNumber: 1, trackNumber: index + 1, title: `Synthetic Track ${index + 1}`, durationMs }));
    const member = numberedMembers([200_000]);
    // A different saved tracklist is a conflict; an equal one needs nothing.
    const different = reviewLookupDocument({ members: member, expectedTracklist: [rows[0]] });
    const conflicted = applyLookupCandidate(different, null, reviewRelease(1, lengths), intent()).application;
    assert.deepEqual([conflicted.conflicts.find(item => item.path === 'album.expectedTracklist')?.lookup, reviewDraftOf(different).album.expectedTracklist], [rows, [rows[0]]]);
    const equal = reviewLookupDocument({ members: member, expectedTracklist: rows });
    const same = applyLookupCandidate(equal, null, reviewRelease(1, lengths), intent()).application;
    assert.deepEqual([pathsOf(same.conflicts).includes('album.expectedTracklist'), pathsOf(same.values).includes('album.expectedTracklist')], [false, false]);
    // Over 100 audio tracks is left out as `size`, an invalid title as `format`; neither offers member values or a pairing.
    const many = reviewLookupDocument({ members: member }), large = applyLookupCandidate(many, null, reviewRelease(1, [200_000, ...Array.from({ length: 100 }, () => 300_000)]), intent()).application;
    assert.deepEqual([large.flagged, large.pairs, pathsOf(large.values).filter(path => path.startsWith('tracks.') || path === 'album.expectedTracklist')],
        [[{ path: 'album.expectedTracklist', reason: 'size' }], null, []]);
    const invalid = reviewRelease(1, lengths);
    invalid.release!.media[0].tracks[1].title = 'Bad\u0007Title';
    const malformed = applyLookupCandidate(reviewLookupDocument({ members: member }), null, invalid, intent()).application;
    assert.deepEqual([malformed.flagged, malformed.pairs], [[{ path: 'album.expectedTracklist', reason: 'format' }], null]);
    // A review whose whole draft is over 48 KB through its members' Artist entries, which the cap leaves out, still gets its tracklist.
    const crowded = reviewLookupDocument({ members: Array.from({ length: 10 }, (_unused, index) => ({ durationMs: 200_000 + index * 10_000, trackNumber: index + 1,
        artists: Array.from({ length: 20 }, (_entry, at) => ({ name: `${'n'.repeat(190)} ${index}-${at}` })) })) });
    assert.ok(draftBytes(crowded.draft) > DRAFT_V2_LIMITS.bytes);
    const filled = applyLookupCandidate(crowded, null, reviewRelease(1, Array.from({ length: 12 }, (_unused, index) => 200_000 + index * 10_000), { credits: 'release' }), intent()).application;
    assert.deepEqual([filled.flagged, (reviewDraftOf(crowded).album.expectedTracklist as unknown[]).length], [[], 12]);
});

test('an Album without members gets an all-missing expected tracklist and an empty pairing; an ambiguous pairing writes Album values only', () => {
    const empty = reviewLookupDocument();
    const filled = applyLookupCandidate(empty, null, reviewRelease(1, [200_000, 210_000]), intent()).application;
    assert.deepEqual([filled.pairs, (reviewDraftOf(empty).album.expectedTracklist as { trackNumber: number }[]).map(row => row.trackNumber)], [[], [1, 2]]);
    // Two members without durations or numbers fit either track: no single pairing, so no tracklist and no member value.
    const ambiguous = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: [{ title: 'One' }, { title: 'Two' }] });
    const albumOnly = applyLookupCandidate(ambiguous, null, reviewRelease(1, [200_000, 210_000], { title: 'Looked Up Album', credits: 'release' }), intent()).application;
    assert.deepEqual([albumOnly.pairs, pathsOf(albumOnly.values), pathsOf(albumOnly.conflicts), albumOnly.flagged], [null, ['album.releaseDate'], ['album.title'], []]);
    assert.deepEqual(reviewDraftOf(ambiguous).tracks.map(track => [track.trackNumber, track.artists]), [[null, []], [null, []]]);
});

test('choosing B after A writes B\'s pairing from the review\'s own numbers, and a re-rank right after an application changes nothing', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: [{ durationMs: 200_000, title: '' }, { durationMs: 210_000, title: '' }] });
    const a = reviewRelease(1, [200_000, 210_000, 300_000], { credits: 'release' }), b = reviewRelease(2, [150_000, 200_000, 210_000], { credits: 'release' });
    const record = { ...completed(doc, [a, b], { input: { trigger: 'catalog', submitted: null }, exactSearchComplete: true }) };
    const first = applyLookupCandidate(doc, null, a, intent()).application;
    assert.deepEqual([first.pairs!.map(pair => pair.trackNumber), reviewDraftOf(doc).tracks.map(track => track.trackNumber)], [[1, 2], [1, 2]]);
    // Numbers A wrote are automatic, so they never constrain B's pairing; B's replace them.
    const second = applyLookupCandidate(doc, first, b, intent()).application;
    assert.deepEqual([second.pairs!.map(pair => pair.trackNumber), reviewDraftOf(doc).tracks.map(track => track.trackNumber), second.conflicts], [[2, 3], [2, 3], []]);
    assert.equal(lookupRerankNeeded(doc, { ...record, applied: second }), false);
    assert.equal(rerankStoredLookup(doc, { ...record, applied: second }, now), null);
});

test('a paired member\'s Artist entries come only from its own track: filled without Artist Credits, absent when agreeing, else one conflict', () => {
    const singer = credit('Synthetic Singer', syntheticMbid(5)), featured = credit('Synthetic Singer', syntheticMbid(5), ['Synthetic Guest', syntheticMbid(6)]);
    const members: ReviewMemberFixture[] = [
        { durationMs: 200_000, trackNumber: 1 },
        { durationMs: 210_000, trackNumber: 2, attributionStatus: 'unknown' },
        { durationMs: 220_000, trackNumber: 3, otherCredits: ['organization'] },
        { durationMs: 230_000, trackNumber: 4, artists: [{ name: 'synthetic singer' }] },
        { durationMs: 240_000, trackNumber: 5, artists: [{ name: 'Other Singer' }] },
        { durationMs: 250_000, trackNumber: 6, otherCredits: ['composer'] },
        { durationMs: 260_000, trackNumber: 7, artists: [{ name: 'Synthetic Singer' }] }];
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members });
    const candidate = reviewRelease(1, [200_000, 210_000, 220_000, 230_000, 240_000, 250_000, 260_000],
        { credits: [singer, singer, singer, singer, singer, singer, featured] });
    const { application } = applyLookupCandidate(doc, null, candidate, intent()), draft = reviewDraftOf(doc), slot = reviewSlot;
    // Members without an Artist Credit (none, attribution unknown, an Organization only) take their own track's credit, never the
    // release's or the Album's.
    for (const index of [0, 1, 2]) {
        assert.deepEqual([draft.tracks[index].artists, doc.draftOrigins![`tracks:${slot(index)}:artists`]],
            [[lookupEntry(reviewKey('Synthetic Singer', slot(index)), 'Synthetic Singer', syntheticMbid(5))], 'automatic'], `member ${index}`);
    }
    // An agreeing member has no value and only gains the ID, recorded with its path.
    assert.deepEqual(draft.tracks[3].artists, [lookupEntry(reviewMemberEntryKey(3, 0), 'synthetic singer', syntheticMbid(5))]);
    assert.ok(application.musicBrainzIds!.some(item => item.path === `tracks.${slot(3)}.artists` && item.entryKey === reviewMemberEntryKey(3, 0) && item.musicBrainzId === syntheticMbid(5)));
    assert.equal(pathsOf(application.values).includes(`tracks.${slot(3)}.artists`), false);
    // A differing member, a composer-only member and a featured-only addition are each one conflict on the whole list.
    assert.deepEqual(application.conflicts.filter(item => item.path.endsWith('.artists')).map(item => [item.path, (item.lookup as ImportArtistEntry[]).map(entry => [entry.key, entry.name, entry.role])]), [
        [`tracks.${slot(4)}.artists`, [[reviewKey('Synthetic Singer', slot(4)), 'Synthetic Singer', 'primary']]],
        [`tracks.${slot(5)}.artists`, [[reviewKey('Synthetic Singer', slot(5)), 'Synthetic Singer', 'primary']]],
        [`tracks.${slot(6)}.artists`, [[reviewMemberEntryKey(6, 0), 'Synthetic Singer', 'primary'], [reviewKey('Synthetic Guest', slot(6)), 'Synthetic Guest', 'featured']]]]);
    assert.deepEqual([draft.tracks[4].artists.map(entry => entry.name), draft.tracks[5].artists, draft.tracks[6].artists.length], [['Other Singer'], [], 1]);
    // A member conflict blocks until answered: `mine` keeps the list, `lookup` writes it and records its IDs with the path.
    const record = { ...completed(doc, [candidate]), applied: application };
    const needed = lookupAnswersNeeded(record, doc, { append: false }).conflicts;
    assert.deepEqual(needed.filter(path => path.endsWith('.artists')), [4, 5, 6].map(index => `tracks.${slot(index)}.artists`));
    const answer = (path: string, value: 'mine' | 'lookup', from: MetadataLookupRecord) =>
        resolveLookupConflicts(doc, from, { run: 1, candidateKey: candidate.key, answers: [{ path: path as `tracks.${string}.artists`, answer: value, base: structuredClone(draft.tracks.find(track => path.includes(track.slotId))!.artists) }] }, now);
    const kept = answer(`tracks.${slot(4)}.artists`, 'mine', record), took = answer(`tracks.${slot(6)}.artists`, 'lookup', kept);
    assert.deepEqual([draft.tracks[4].artists.map(entry => entry.name), draft.tracks[6].artists.map(entry => [entry.name, entry.role, entry.musicBrainzId]), doc.draftOrigins![`tracks:${slot(6)}:artists`]],
        [['Other Singer'], [['Synthetic Singer', 'primary', syntheticMbid(5)], ['Synthetic Guest', 'featured', syntheticMbid(6)]], 'administrator']);
    assert.ok(took.applied!.musicBrainzIds!.some(item => item.path === `tracks.${slot(6)}.artists` && item.entryKey === reviewKey('Synthetic Guest', slot(6)) && item.musicBrainzId === syntheticMbid(6)));
    assert.deepEqual(lookupAnswersNeeded(took, doc, { append: false }).conflicts.filter(path => path.endsWith('.artists')), [`tracks.${slot(5)}.artists`]);
});

test('a member whose track has no usable credit, or whose capture is incomplete, is left as it is and flagged; an iTunes-only track artist stays one entry', () => {
    const placeholder: LookupArtistCredit[] = [{ name: 'Various Artists', joinPhrase: '', artistId: '89ad4ac3-39f7-470e-963a-56509c546377', artistName: 'Various Artists' }];
    const doc = reviewLookupDocument({ members: [{ durationMs: 200_000, trackNumber: 1 }, { durationMs: 210_000, trackNumber: 2 }, { durationMs: 220_000, trackNumber: 3, complete: false },
        { durationMs: 230_000, trackNumber: 4, complete: 'unreadable' }] });
    const { application } = applyLookupCandidate(doc, null, reviewRelease(1, [200_000, 210_000, 220_000, 230_000], { credits: [placeholder, undefined, 'release', 'release'] }), intent());
    assert.deepEqual(application.flagged, [{ path: `tracks.${reviewSlot(0)}.artists`, reason: 'placeholder' }, { path: `tracks.${reviewSlot(1)}.artists`, reason: 'noTrackCredit' },
        { path: `tracks.${reviewSlot(2)}.artists`, reason: 'notApplicable' }, { path: `tracks.${reviewSlot(3)}.artists`, reason: 'notApplicable' }]);
    assert.deepEqual(reviewDraftOf(doc).tracks.map(track => track.artists), [[], [], [], []]);
    assert.equal(application.conflicts.some(item => item.path.startsWith('tracks.') && item.path.endsWith('.artists')), false);
    // An iTunes-only candidate's track artist string is one primary entry, never split at its featuring phrase.
    const itunes = reviewLookupDocument({ members: [{ durationMs: 210_000, trackNumber: 1 }, { durationMs: 220_000, trackNumber: 2 }] });
    applyLookupCandidate(itunes, null, itunesStored('1613862586', 'noRelease'), intent());
    assert.deepEqual(reviewDraftOf(itunes).tracks.map(track => track.artists.map(entry => [entry.name, entry.role, entry.musicBrainzId])),
        [[['Synthetic Ensemble feat. Synthetic Guest', 'primary', null]], [['Synthetic Ensemble feat. Synthetic Guest', 'primary', null]]]);
});

test('choosing B after A, or none, replaces or removes automatic member entries and removes a member MusicBrainz ID that A supplied', () => {
    const doc = reviewLookupDocument({ members: [{ durationMs: 200_000, trackNumber: 1 }, { durationMs: 210_000, trackNumber: 2, artists: [{ name: 'Synthetic Singer' }] }] });
    const a = reviewRelease(1, [200_000, 210_000], { credits: [credit('First Singer', syntheticMbid(5)), credit('Synthetic Singer', syntheticMbid(6))] });
    const b = reviewRelease(2, [200_000, 210_000], { credits: [credit('Second Singer', syntheticMbid(7)), [{ name: 'Synthetic Singer', joinPhrase: '', artistId: '', artistName: 'Synthetic Singer' }]] });
    const first = applyLookupCandidate(doc, null, a, intent()).application, draft = reviewDraftOf(doc);
    assert.deepEqual(draft.tracks.map(track => track.artists.map(entry => [entry.name, entry.musicBrainzId])), [[['First Singer', syntheticMbid(5)]], [['Synthetic Singer', syntheticMbid(6)]]]);
    // B replaces the automatic entries and removes the ID A gave the agreeing member, which B does not offer.
    const second = applyLookupCandidate(doc, first, b, intent()).application;
    assert.deepEqual(draft.tracks.map(track => track.artists.map(entry => [entry.name, entry.musicBrainzId])), [[['Second Singer', syntheticMbid(7)]], [['Synthetic Singer', null]]]);
    assert.deepEqual(second.musicBrainzIds, [{ path: `tracks.${reviewSlot(0)}.artists`, entryKey: reviewKey('Second Singer', reviewSlot(0)), musicBrainzId: syntheticMbid(7) }]);
    // A candidate offering the agreeing member another ID gives it that one, recorded under the saved entry's key.
    const third = applyLookupCandidate(doc, second, reviewRelease(3, [200_000, 210_000], { credits: [credit('Second Singer', syntheticMbid(7)), credit('Synthetic Singer', syntheticMbid(8))] }), intent()).application;
    assert.deepEqual([draft.tracks[1].artists[0].musicBrainzId, third.musicBrainzIds!.find(item => item.path === `tracks.${reviewSlot(1)}.artists`)?.entryKey], [syntheticMbid(8), reviewMemberEntryKey(1, 0)]);
    // None empties the automatic member and removes the supplied ID again.
    applyLookupCandidate(doc, third, null, none());
    assert.deepEqual(draft.tracks.map(track => track.artists.map(entry => [entry.name, entry.musicBrainzId])), [[], [['Synthetic Singer', null]]]);
    assert.equal(doc.draftOrigins![`tracks:${reviewSlot(0)}:artists`], undefined);
});

test('a lookup answer never records the IDs the saved entries kept, so choosing none keeps them and a later renamed credit still agrees by ID', () => {
    const lead = { name: 'Synthetic Lead', musicBrainzId: syntheticMbid(1) }, second = { name: 'Synthetic Second', musicBrainzId: syntheticMbid(2) };
    const doc = reviewLookupDocument({ albumEntries: [lead, second], members: [{ durationMs: 200_000, trackNumber: 1, artists: [lead, second] }] });
    const reordered: LookupArtistCredit[] = [{ name: 'Synthetic Second', joinPhrase: ', ', artistId: syntheticMbid(2), artistName: 'Synthetic Second' },
        { name: 'Synthetic Lead', joinPhrase: '', artistId: syntheticMbid(1), artistName: 'Synthetic Lead' }];
    const candidate = reviewRelease(1, [200_000], { releaseCredit: reordered, credits: [reordered] }), member = `tracks.${reviewSlot(0)}.artists` as const;
    const applied = applyLookupCandidate(doc, null, candidate, intent()).application, draft = reviewDraftOf(doc);
    assert.deepEqual(pathsOf(applied.conflicts).filter(path => path.endsWith('.artists')), ['album.artists', member]);
    // Taking both reordered lists writes the saved entries' own IDs, which the application never records as supplied.
    const answered = resolveLookupConflicts(doc, { ...completed(doc, [candidate]), applied }, { run: 1, candidateKey: candidate.key, answers: [
        { path: 'album.artists', answer: 'lookup', base: structuredClone(draft.album.artists) }, { path: member, answer: 'lookup', base: structuredClone(draft.tracks[0].artists) }] }, now);
    const ids = (entries: ImportArtistEntry[]) => entries.map(entry => [entry.name, entry.musicBrainzId]);
    const swapped = [['Synthetic Second', syntheticMbid(2)], ['Synthetic Lead', syntheticMbid(1)]];
    assert.deepEqual([ids(draft.album.artists), ids(draft.tracks[0].artists), answered.applied!.musicBrainzIds], [swapped, swapped, undefined]);
    // Choosing none keeps them, as their Artists do.
    const none_ = applyLookupCandidate(doc, answered.applied, null, none()).application;
    assert.deepEqual([ids(draft.album.artists), ids(draft.tracks[0].artists)], [swapped, swapped]);
    // A later candidate crediting the second artist under a new name still agrees through the ID its Artist keeps.
    const renamed: LookupArtistCredit[] = [{ ...reordered[0], name: 'Renamed Second', artistName: 'Renamed Second' }, reordered[1]];
    const later = applyLookupCandidate(doc, none_, reviewRelease(3, [200_000], { releaseCredit: renamed, credits: [renamed] }), intent()).application;
    assert.deepEqual([later.conflicts.filter(item => item.path.endsWith('.artists')), ids(draft.album.artists), ids(draft.tracks[0].artists)], [[], swapped, swapped]);
});

test('a member whose Artist keeps another ID under the same name keeps it and gets an ID conflict that only an explicit answer replaces', () => {
    const doc = reviewLookupDocument({ members: [{ durationMs: 200_000, trackNumber: 1, artists: [{ name: 'Synthetic Singer', musicBrainzId: syntheticMbid(77) }] }] });
    const candidate = reviewRelease(1, [200_000], { credits: [credit('Synthetic Singer', syntheticMbid(5))] }), path = `tracks.${reviewSlot(0)}.artists` as const;
    const applied = applyLookupCandidate(doc, null, candidate, intent()).application, draft = reviewDraftOf(doc);
    const replacing = [lookupEntry(reviewMemberEntryKey(0, 0), 'Synthetic Singer', syntheticMbid(5))];
    assert.deepEqual(applied.conflicts.filter(item => item.path === path), [{ path, lookup: replacing, slotId: reviewSlot(0), answer: null, musicBrainzId: true }]);
    assert.deepEqual([draft.tracks[0].artists, pathsOf(applied.values).includes(path)], [[lookupEntry(reviewMemberEntryKey(0, 0), 'Synthetic Singer', syntheticMbid(77))], false]);
    const record = { ...completed(doc, [candidate]), applied };
    assert.ok(lookupAnswersNeeded(record, doc, { append: false }).conflicts.includes(path));
    // Keeping the current Credits leaves the kept ID; using the lookup value replaces it and records the new one with its path.
    const kept = resolveLookupConflicts(doc, record, { run: 1, candidateKey: candidate.key, answers: [{ path, answer: 'mine', base: structuredClone(draft.tracks[0].artists) }] }, now);
    assert.deepEqual([draft.tracks[0].artists[0].musicBrainzId, lookupAnswersNeeded(kept, doc, { append: false }).conflicts.includes(path)], [syntheticMbid(77), false]);
    const took = resolveLookupConflicts(doc, record, { run: 1, candidateKey: candidate.key, answers: [{ path, answer: 'lookup', base: structuredClone(draft.tracks[0].artists) }] }, now);
    assert.deepEqual([draft.tracks[0].artists, took.applied!.musicBrainzIds], [replacing, [{ path, entryKey: reviewMemberEntryKey(0, 0), musicBrainzId: syntheticMbid(5) }]]);
});

