test('a refused preselection leaves the review document as it was, since a re-ranking save persists the document whole', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Lead'], members: numberedMembers([210_000, 220_000]) }), before = copy(doc);
    const run = completed(doc, [stored(synthetic(1))], { run: 2, input: { trigger: 'catalog', submitted: null }, grantSource: 'create', files: catalogReviewLookupFileSet(doc).files,
        exactSearchComplete: true });
    const outdated = { ...run, ranking: { ...run.ranking!, files: [] } };
    // The application refuses after it changed the draft: reading the value revision, which it bumps last, refuses.
    const refusing = new Proxy(doc, { get: (target, key, receiver) => {
        if (key === 'valueRevision') throw new AdminImportError(409, 'ADMIN_IMPORT_LOOKUP_STALE');
        return Reflect.get(target, key, receiver);
    } });
    const refused = rerankStoredLookup(refusing, outdated, now, other)!;
    assert.deepEqual([refused.changed, refused.record.applied, refused.record.ranking!.preselection?.candidateKey], [false, null, `musicbrainz:${mbid(1)}`]);
    assert.deepEqual(doc, before);
    // The same re-rank without the refusal applies the preselection.
    assert.equal(rerankStoredLookup(doc, outdated, now, other)!.changed, true);
    assert.notDeepEqual(doc.draft, before.draft);
});

test('member Artist entries past 512 distinct identities across the Album and members are left out as size', () => {
    const count = 30, lengths = Array.from({ length: count }, (_unused, index) => 100_000 + index * 10_000);
    const credits = lengths.map((_length, track) => Array.from({ length: 20 }, (_entry, at): LookupArtistCredit => ({ name: `Synthetic Artist ${track}-${at}`, joinPhrase: at === 19 ? '' : ', ',
        artistId: syntheticMbid(1000 + track * 20 + at), artistName: `Synthetic Artist ${track}-${at}` })));
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: numberedMembers(lengths) });
    const { application } = applyLookupCandidate(doc, null, reviewRelease(1, lengths, { credits }), intent());
    // The Album's one entry and 25 members' 20 each make 501; the 26th member would make 521.
    assert.deepEqual(application.flagged.map(item => [item.path, item.reason]), Array.from({ length: 5 }, (_unused, index) => [`tracks.${reviewSlot(25 + index)}.artists`, 'size']));
    assert.deepEqual([reviewDraftOf(doc).tracks[24].artists.length, reviewDraftOf(doc).tracks[25].artists.length], [20, 0]);
});

test('a review\'s Artist entries are not applicable while not every Artist Credit is shown, nor its label while it is read-only', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Other Ensemble' }], albumComplete: false, label: 'other' });
    const { application } = applyLookupCandidate(doc, null, reviewRelease(1, [200_000], { label: { name: 'Looked Up Label', labelId: syntheticMbid(40) } }), intent());
    assert.deepEqual([application.flagged, pathsOf(application.conflicts)], [[{ path: 'album.artists', reason: 'notApplicable' }, { path: 'album.label', reason: 'notApplicable' }], []]);
    assert.deepEqual([reviewDraftOf(doc).album.artists.map(entry => entry.name), reviewDraftOf(doc).album.label], [['Other Ensemble'], { name: 'Synthetic Label', musicBrainzId: null }]);
    // A label of the same name and another ID stays a MusicBrainz ID conflict, as for imports.
    const label = reviewLookupDocument();
    reviewDraftOf(label).album.label = { name: 'Looked Up Label', musicBrainzId: syntheticMbid(41) };
    const idConflict = applyLookupCandidate(label, null, reviewRelease(1, [200_000], { label: { name: 'Looked Up Label', labelId: syntheticMbid(40) } }), intent()).application;
    assert.deepEqual(idConflict.conflicts.filter(item => item.path === 'album.label').map(item => [item.lookup, item.musicBrainzId]), [[{ name: 'Looked Up Label', musicBrainzId: syntheticMbid(40) }, true]]);
});

test('answering a review\'s expected tracklist conflict measures the review\'s capped draft, so a large draft still takes it', () => {
    const lengths = Array.from({ length: 12 }, (_unused, index) => 200_000 + index * 10_000);
    const doc = reviewLookupDocument({ expectedTracklist: [{ discNumber: 1, trackNumber: 1, title: 'Saved Row', durationMs: null }],
        members: Array.from({ length: 10 }, (_unused, index) => ({ durationMs: lengths[index], trackNumber: index + 1,
            artists: Array.from({ length: 20 }, (_entry, at) => ({ name: `${'n'.repeat(190)} ${index}-${at}` })) })) });
    const candidate = reviewRelease(1, lengths), applied = applyLookupCandidate(doc, null, candidate, intent()).application;
    assert.ok(draftBytes(doc.draft) > DRAFT_V2_LIMITS.bytes);
    const base = structuredClone(reviewDraftOf(doc).album.expectedTracklist);
    const answered = resolveLookupConflicts(doc, { ...completed(doc, [candidate]), applied }, { run: 1, candidateKey: candidate.key, answers: [{ path: 'album.expectedTracklist', answer: 'lookup', base }] }, now);
    assert.deepEqual([(reviewDraftOf(doc).album.expectedTracklist as unknown[]).length, doc.draftOrigins!['album:expectedTracklist'], answered.applied!.conflicts.find(item => item.path === 'album.expectedTracklist')?.answer],
        [12, 'administrator', 'lookup']);
    // A stale base is refused and writes nothing.
    assert.throws(() => resolveLookupConflicts(doc, { ...completed(doc, [candidate]), applied }, { run: 1, candidateKey: candidate.key, answers: [{ path: 'album.expectedTracklist', answer: 'mine', base }] }, now),
        code('ADMIN_IMPORT_FIELD_CONFLICT'));
});

test('a review re-rank applies a new sole preselection over an application an earlier run left, and a run without a single pairing applies nothing', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Lead'], members: numberedMembers([210_000, 220_000]) }), files = catalogReviewLookupFileSet(doc).files;
    const run = completed(doc, [stored(synthetic(1))], { run: 2, input: { trigger: 'catalog', submitted: null }, grantSource: 'create', files, exactSearchComplete: true });
    const earlier: LookupApplication = { run: 1, candidateKey: null, releaseId: null, choice: 'none', basis: null, actorId: actor, operationId: mbid(700), at: now, paths: [], values: [],
        conflicts: [], flagged: [], pairs: null };
    const outdated = { ...run, applied: earlier, ranking: { ...run.ranking!, files: [] } };
    const reranked = rerankStoredLookup(doc, outdated, now, other)!;
    assert.deepEqual([reranked.changed, reranked.record.applied?.run, reranked.record.applied?.choice, reranked.record.applied?.candidateKey, reranked.record.applied?.actorId,
        reranked.record.applied?.pairs?.map(pair => pair.trackNumber), reviewDraftOf(doc).album.expectedTracklist], [true, 2, 'preselected', `musicbrainz:${mbid(1)}`, other, [1, 2],
        [1, 2].map(trackNumber => ({ discNumber: 1, trackNumber, title: trackNumber === 1 ? 'First Song' : 'Second Song', durationMs: 200_000 + trackNumber * 10_000 }))]);
    // Members without durations or numbers fit either track: nothing is preselected, and the earlier run's application stays.
    const unpaired = reviewLookupDocument({ primaryNames: ['Synthetic Lead'], members: [{ title: 'One' }, { title: 'Two' }] }), before = copy(unpaired);
    const ambiguous = completed(unpaired, [stored(synthetic(1))], { run: 2, input: { trigger: 'catalog', submitted: null }, grantSource: 'create',
        files: catalogReviewLookupFileSet(unpaired).files, exactSearchComplete: true });
    const kept = rerankStoredLookup(unpaired, { ...ambiguous, applied: earlier, ranking: { ...ambiguous.ranking!, files: [] } }, now, other)!;
    assert.deepEqual([kept.record.ranking!.preselection, kept.record.applied, unpaired.draft, unpaired.draftOrigins], [null, earlier, before.draft, before.draftOrigins]);
});
